if __name__ == "__main__":
    out = Path(__file__).resolve().parent.parent / "fields"
    n = 0
    for p in out.glob("*.json"):
        f = json.loads(p.read_text(encoding="utf-8"))
        changed = False
        for q in f["quiz"]:
            if q["id"] in D:
                q["options"] = [q["options"][q["answer"]]] + D[q["id"]]
                q["answer"] = 0
                changed = True
                n += 1
        if changed:
            p.write_text(json.dumps(f, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"  replaced distractors in {n} questions")
